local gl = require("opengl")
function draw()
  gl.Disable(gl.DEPTH_TEST)
  gl.Enable(gl.BLEND)
  gl.BlendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA)
  gl.Begin(gl.QUADS)
  gl.Color({ 1, 0, 0, 1 })
  gl.Vertex(-1, -1)
  gl.Vertex(1, -1)
  gl.Vertex(1, 1)
  gl.Vertex(-1, 1)
  gl.End()
  gl.Disable(gl.BLEND)
end
